// Индивидуальная программа «Машинное обучение», глава 9 — решающие деревья.
// Определение и геометрия, критерии информативности, почему оптимальное дерево построить трудно,
// жадный алгоритм CART, переобучение, регуляризация (ранний останов и обрезка), свойства деревьев,
// реализация без библиотек, scikit-learn, вопросы с собеседований.
// Иллюстрации считаются здесь же: деревья для карт решений и регрессии обучены в scikit-learn 1.9
// (make_moons, seed 0; равномерные точки, seed 3; синус с шумом, seed 0) и записаны массивами узлов.
// Вывод кода получен запуском приведённых листингов в Python 3.13, NumPy 2.1 и scikit-learn 1.9.
// Задания к главе пока нет (submit: 'soon' в index.js). Файл без импортов: его грузит и админка.

const plain = text => ({ t: 'example', label: 'Простыми словами', text })

const grid = (a, b, n) => Array.from({ length: n + 1 }, (_, i) => a + ((b - a) * i) / n)
const log2 = p => (p <= 0 ? 0 : Math.log2(p))

