const predictTree = (nodes, x) => {
  let i = 0
  while (nodes[i][0] !== -1) i = x[nodes[i][0]] <= nodes[i][1] ? nodes[i][2] : nodes[i][3]
  return nodes[i][4]
}

// Карта решений: квадратные клетки со стороной step, раскрашенные по ответу дерева
function regionCells(nodes, [x0, x1, y0, y1], step) {
  const cells = []
  for (let x = x0 + step / 2; x < x1; x += step) {
    for (let y = y0 + step / 2; y < y1; y += step) cells.push([+x.toFixed(3), +y.toFixed(3), predictTree(nodes, [x, y])])
  }
  return cells
}

const MOONS_BOX = [-1.6, 2.5, -1.2, 1.6]
const regionPlot = (nodes, caption) => ({ t: 'plot', caption, equal: true, axesAtZero: false, legend: false,
  x: { min: MOONS_BOX[0], max: MOONS_BOX[1], step: 0.5, label: 'x₁' }, y: { min: MOONS_BOX[2], max: MOONS_BOX[3], step: 0.5, label: 'x₂' },
  series: [
    { type: 'cells', size: 0.1, points: regionCells(nodes, MOONS_BOX, 0.1), colors: ['blue', 'orange'], opacity: 0.22 },
    { type: 'scatter', points: MOONS0, color: 'blue', r: 3.8, opacity: 1, stroke: '#0B0B0E' },
    { type: 'scatter', points: MOONS1, color: 'orange', r: 3.8, opacity: 1, stroke: '#0B0B0E' },
  ] })

const regLine = nodes => grid(0, 6, 1200).map(x => [x, predictTree(nodes, [x])])

